   374→      btn.on('pointerdown', () => this.handleClaimReward());
   375→    }
   376→  }
   377→
   378→  /** 보상받기 버튼 클릭 처리 */
   379→  private async handleClaimReward() {
   380→    if (!this.rewardBtnBg || !this.rewardBtnLabel) return;
   381→
   382→    // 처리 중 표시 (중복 클릭 방지)
