    49→
    50→function pullOne(): { id: string; grade: string } {
    51→  const total = POOL.reduce((s, c) => s + c.weight, 0);
    52→  let r = Math.random() * total;
    53→  for (const c of POOL) {
    54→    r -= c.weight;
    55→    if (r <= 0) return { id: c.id, grade: c.grade };
    56→  }
    57→  return { id: POOL[POOL.length - 1].id, grade: POOL[POOL.length - 1].grade };
    58→}
