    60→// ── 요청 처리 ───────────────────────────────────────────────────────────
    61→Deno.serve(async (req: Request) => {
    62→  if (req.method === 'OPTIONS') {
    63→    return new Response('ok', { headers: corsHeaders });
    64→  }
    65→
    66→  try {
    67→    const { pullType } = await req.json(); // 'single' | 'multi'
    68→
    69→    if (pullType !== 'single' && pullType !== 'multi') {
    70→      return new Response(
    71→        JSON.stringify({ error: 'Invalid pullType' }),
    72→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    73→      );
    74→    }
    75→
    76→    const cost = pullType === 'multi' ? 900 : 100;
    77→    const count = pullType === 'multi' ? 10 : 1;
    78→
    79→    // 인증
    80→    const authHeader = req.headers.get('Authorization');
    81→    if (!authHeader) {
    82→      return new Response(
    83→        JSON.stringify({ error: 'Missing authorization header' }),
    84→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    85→      );
    86→    }
    87→
    88→    const supabaseUser = createClient(
    89→      Deno.env.get('SUPABASE_URL') ?? '',
    90→      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
    91→      { global: { headers: { Authorization: authHeader } } }
    92→    );
    93→
    94→    const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
    95→    if (authError || !user) {
    96→      return new Response(
    97→        JSON.stringify({ error: 'Unauthorized' }),
    98→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    99→      );
   100→    }
   101→
   102→    const supabaseAdmin = createClient(
   103→      Deno.env.get('SUPABASE_URL') ?? '',
   104→      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
   105→    );
   106→
   107→    // ── 1. SKOR 잔액 + 보유 캐릭터 + 보유 배경화면 병렬 조회 ────────
   108→    const [{ data: skorData }, { data: owned }, { data: ownedWp }] = await Promise.all([
   109→      supabaseAdmin.from('user_skor').select('balance').eq('user_id', user.id).single(),
   110→      supabaseAdmin.from('user_characters').select('character_id').eq('user_id', user.id),
   111→      supabaseAdmin.from('user_wallpapers').select('wallpaper_id').eq('user_id', user.id),
   112→    ]);
   113→
   114→    const balance = skorData?.balance ?? 0;
   115→    if (balance < cost) {
   116→      return new Response(
   117→        JSON.stringify({ error: 'Insufficient SKOR', balance }),
   118→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   119→      );
   120→    }
   121→
   122→    // ── 2. 슬롯별 결정: 각 슬롯은 배경화면 또는 캐릭터 중 하나
   123→    //       총합 = count, 추가 드롭 없음 ────────────────────────────────
   124→    const ownedSet = new Set((owned ?? []).map((r: { character_id: string }) => r.character_id));
   125→    const ownedWpSet = new Set((ownedWp ?? []).map((r: { wallpaper_id: string }) => r.wallpaper_id));
   126→
   127→    const characters: { id: string; grade: string; isNew: boolean }[] = [];
   128→    const wallpapers: { id: string; isNew: boolean }[] = [];
   129→
   130→    for (let i = 0; i < count; i++) {
   131→      if (Math.random() < WP_DROP_CHANCE) {
   132→        // 이 슬롯은 배경화면
   133→        const wp = pullWallpaper();
   134→        wallpapers.push({ id: wp.id, isNew: !ownedWpSet.has(wp.id) });
   135→        ownedWpSet.add(wp.id); // 같은 pull 내 중복 isNew 방지
   136→      } else {
   137→        // 이 슬롯은 캐릭터
   138→        const char = pullOne();
   139→        characters.push({ id: char.id, grade: char.grade, isNew: !ownedSet.has(char.id) });
   140→      }
   141→    }
   142→
   143→    // ── 3. 신규 배경화면 등록 ────────────────────────────────────────────
   144→    const newWps = wallpapers
   145→      .filter(w => w.isNew)
   146→      .map(w => ({ user_id: user.id, wallpaper_id: w.id }));
   147→
   148→    // ── 4. 신규 캐릭터 등록 + 중복 카운트 증가 + SKOR 차감 병렬 처리 ─────
   149→    // 같은 캐릭터가 10연차에서 중복 등장할 수 있으므로 횟수 집계 후 처리
   150→    const newChars = [...new Map(
   151→      characters
   152→        .filter(c => c.isNew)
   153→        .map(c => [c.id, { user_id: user.id, character_id: c.id }])
   154→    ).values()];
   155→
   156→    // 중복 캐릭터별 횟수 집계 (같은 캐릭터가 10연차에서 2번 나오면 +2)
   157→    const dupCountMap = new Map<string, number>();
   158→    characters.filter(c => !c.isNew).forEach(c => {
   159→      dupCountMap.set(c.id, (dupCountMap.get(c.id) ?? 0) + 1);
   160→    });
   161→
   162→    const newBalance = balance - cost;
   163→    const [charResult, , , skorResult] = await Promise.all([
   164→      newChars.length > 0
   165→        ? supabaseAdmin.from('user_characters').upsert(newChars, { onConflict: 'user_id,character_id' })
   166→        : Promise.resolve({ error: null }),
   167→      // 중복 카운트 증가: RPC로 atomic increment
   168→      dupCountMap.size > 0
   169→        ? Promise.all([...dupCountMap.entries()].map(([charId, inc]) =>
   170→            supabaseAdmin.rpc('increment_duplicate_count', {
   171→              p_user_id: user.id,
   172→              p_character_id: charId,
   173→              p_amount: inc,
   174→            })
   175→          ))
   176→        : Promise.resolve(null),
   177→      // 신규 배경화면 등록
   178→      newWps.length > 0
   179→        ? supabaseAdmin.from('user_wallpapers').upsert(newWps, { onConflict: 'user_id,wallpaper_id' })
   180→        : Promise.resolve({ error: null }),
   181→      supabaseAdmin.from('user_skor').upsert(
   182→        { user_id: user.id, balance: newBalance, updated_at: new Date().toISOString() },
   183→        { onConflict: 'user_id' }
   184→      ),
   185→    ]);
   186→
   187→    if (charResult && 'error' in charResult && charResult.error) {
   188→      console.error('user_characters upsert 실패:', charResult.error);
   189→      return new Response(
   190→        JSON.stringify({ error: 'Failed to save characters', detail: charResult.error }),
   191→        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   192→      );
   193→    }
   194→    if (skorResult && 'error' in skorResult && skorResult.error) {
   195→      console.error('user_skor upsert 실패:', skorResult.error);
   196→    }
   197→
   198→    // ── 6. 응답 ───────────────────────────────────────────────────────
   199→    const hasUR = characters.some(c => c.grade === 'UR');
   200→
   201→    return new Response(
   202→      JSON.stringify({
   203→        success: true,
   204→        video: hasUR ? 'red' : 'green',
   205→        characters,
   206→        wallpapers,
   207→        remainingSkor: Math.floor(newBalance),
   208→      }),
   209→      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   210→    );
   211→  } catch (error) {
   212→    console.error('Unexpected error:', error);
   213→    return new Response(
   214→      JSON.stringify({ error: 'Internal server error' }),
   215→      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   216→    );
   217→  }
   218→});
