   280→/** duplicate_count → 각성 단계 계산 (모든 등급 최대 ★5) */
   281→export function getAwakeningLevel(grade: string, duplicateCount: number): number {
   282→  if (grade === 'R') {
   283→    if (duplicateCount >= 100) return 5;
   284→    if (duplicateCount >= 75)  return 4;
   285→    if (duplicateCount >= 50)  return 3;
   286→    if (duplicateCount >= 25)  return 2;
   287→    if (duplicateCount >= 10)  return 1;
   288→  } else if (grade === 'SR') {
   289→    if (duplicateCount >= 40) return 5;
   290→    if (duplicateCount >= 25) return 4;
   291→    if (duplicateCount >= 15) return 3;
   292→    if (duplicateCount >= 7)  return 2;
   293→    if (duplicateCount >= 3)  return 1;
   294→  } else if (grade === 'UR') {
   295→    if (duplicateCount >= 10) return 5;
   296→    if (duplicateCount >= 6)  return 4;
   297→    if (duplicateCount >= 4)  return 3;
   298→    if (duplicateCount >= 2)  return 2;
   299→    if (duplicateCount >= 1)  return 1;
   300→  }
   301→  return 0;
   302→}
   303→
   304→const DUPES_KEY     = 'duplicateCounts';
   305→const DUPES_SIG_KEY = 'duplicateCountsSig';
   306→const _DUPES_SALT   = 'ddong-dupes-\u0076\u0032';
   307→
   308→/** djb2 해시 — key:value 쌍을 정렬 후 직렬화해 서명 */
   309→function _signDupes(map: Record<string, number>): string {
   310→  const str = Object.entries(map)
   311→    .sort(([a], [b]) => a.localeCompare(b))
   312→    .map(([k, v]) => `${k}:${v}`)
   313→    .join(',') + _DUPES_SALT;
   314→  let h = 5381;
   315→  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
   316→  return h.toString(36);
   317→}
   318→
   319→function _saveDupes(map: Record<string, number>): void {
   320→  localStorage.setItem(DUPES_KEY, JSON.stringify(map));
   321→  localStorage.setItem(DUPES_SIG_KEY, _signDupes(map));
   322→}
   323→
   324→/** 캐릭터별 중복 획득 횟수 반환. 서명 불일치 시 변조로 판단해 전체 초기화. */
   325→export function getDuplicateCount(id: string): number {
   326→  try {
   327→    const raw = localStorage.getItem(DUPES_KEY);
   328→    const sig = localStorage.getItem(DUPES_SIG_KEY);
   329→    const map: Record<string, number> = raw ? JSON.parse(raw) : {};
   330→
   331→    if (sig === null) {
   332→      // 서명 미존재 → 기존 데이터 마이그레이션: 신뢰하고 서명 최초 발급
   333→      _saveDupes(map);
   334→      return map[id] ?? 0;
   335→    }
   336→
   337→    // 서명 불일치 → 변조로 판단, 전체 초기화
   338→    if (sig !== _signDupes(map)) {
   339→      _saveDupes({});
   340→      return 0;
   341→    }
   342→
   343→    return map[id] ?? 0;
   344→  } catch {
   345→    return 0;
   346→  }
   347→}
   348→
   349→/** 캐릭터별 중복 획득 횟수 저장 (뽑기 완료 후 호출) */
   350→export function setDuplicateCount(id: string, count: number): void {
   351→  try {
   352→    const raw = localStorage.getItem(DUPES_KEY);
   353→    const sig = localStorage.getItem(DUPES_SIG_KEY);
   354→    const map: Record<string, number> = raw ? JSON.parse(raw) : {};
   355→
   356→    // 변조된 상태에서 쓰기 시도 → 기존 맵 무시하고 새로 시작
   357→    if (sig !== null && sig !== _signDupes(map)) {
   358→      _saveDupes({ [id]: count });
   359→      return;
   360→    }
   361→
   362→    map[id] = count;
   363→    _saveDupes(map);
   364→  } catch { /* ignore */ }
   365→}
