   367→const OWNED_KEY = 'ownedCharacters';
   368→const OWNED_SIG_KEY = 'ownedCharactersSig';
   369→const SELECTED_KEY = 'selectedCharacter';
   370→const _SIG_SALT = 'ddong-v2-\u0073\u006b\u006f\u0072';
   371→
   372→/** djb2 해시 → base36 문자열 (무결성 서명용) */
   373→function _sign(list: string[]): string {
   374→  const str = [...list].sort().join(',') + _SIG_SALT;
   375→  let h = 5381;
   376→  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
   377→  return h.toString(36);
   378→}
   379→
   380→/** 보유 목록과 서명을 함께 저장 (내부 전용) */
   381→function _saveOwned(list: string[]): void {
   382→  localStorage.setItem(OWNED_KEY, JSON.stringify(list));
   383→  localStorage.setItem(OWNED_SIG_KEY, _sign(list));
   384→}
   385→
   386→/** 보유 캐릭터 목록 반환. 서명 불일치 시 변조로 판단하여 초기화. */
   387→export function getOwnedCharacters(): string[] {
   388→  try {
   389→    const raw = localStorage.getItem(OWNED_KEY);
   390→    const sig = localStorage.getItem(OWNED_SIG_KEY);
   391→    const list: string[] = raw ? JSON.parse(raw) : [];
   392→    if (!list.includes('chibi')) list.unshift('chibi');
   393→
   394→    if (sig === null) {
   395→      // 서명 미존재 → 기존 데이터 마이그레이션: 목록을 신뢰하고 서명 최초 발급
   396→      _saveOwned(list);
   397→      return list;
   398→    }
   399→
   400→    // 서명 존재하지만 불일치 → 변조로 판단, chibi만 남김
   401→    if (sig !== _sign(list)) {
   402→      _saveOwned(['chibi']);
   403→      return ['chibi'];
   404→    }
   405→
   406→    return list;
   407→  } catch {
   408→    return ['chibi'];
   409→  }
   410→}
   411→
   412→/** 서버 동기화 등 외부에서 목록 전체를 덮어쓸 때 사용 (서명 함께 갱신) */
   413→export function setOwnedCharacters(list: string[]): void {
