// ── 3. 신규 배경화면 등록 ────────────────────────────────────────────
const newWps = wallpapers
  .filter(w => w.isNew)
  .map(w => ({ user_id: user.id, wallpaper_id: w.id }));

// ── 4. 신규 캐릭터 등록 + 중복 카운트 증가 + SKOR 차감 병렬 처리 ─────
// 같은 캐릭터가 10연차에서 중복 등장할 수 있으므로 횟수 집계 후 처리
